vec3 blurSample(vec2 uv, float radiusPx) {
	if (radiusPx < 0.25) return texture(iChannel0, uv).rgb;
	vec2 texel = radiusPx / iResolution.xy;
	vec3 sum = vec3(0.0);
	float wsum = 0.0;
	const int R = 4; // 9x9 taps
	for (int y = -R; y <= R; y++) {
		for (int x = -R; x <= R; x++) {
			vec2 o = vec2(float(x), float(y)) / float(R);
			float w = exp(-dot(o, o) * 2.0);
			sum += texture(iChannel0, uv + o * texel).rgb * w;
			wsum += w;
		}
	}
	return sum / wsum;
