vec3 gradientBackdrop(vec2 uv) {
	vec2 tex = iChannelResolution[1].xy;
	float imgAsp = tex.x / tex.y;
	float scrAsp = iResolution.x / iResolution.y;
	vec2 vuv = uv;
	if (scrAsp > imgAsp) {
